import {CREATOR_ORIGIN,CREATOR_TAGS,CREATOR_SERVERS,CREATOR_COLORS,CREATOR_TIERS,CREATOR_SIDES,CREATOR_REPORTS,creatorEscape as e,normalizeCreator,normalizeTag,normalizeChannel,normalizeVideo,videoThumbnail} from './creators-model.js';
const paths={play:'<path d="m9 7 8 5-8 5V7Z" fill="currentColor" stroke="none"/><rect x="3" y="4" width="18" height="16" rx="5"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',star:'<path d="m12 3 2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-2.9-5.6 2.9 1.1-6.2L3 9.6l6.2-.9L12 3Z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',key:'<circle cx="8" cy="8" r="4"/><path d="m11 11 9 9m-3-3 3-3m-6 0 3-3"/>'};
const icon=name=>`<svg class="creator-icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.play}</svg>`;
const date=value=>new Intl.DateTimeFormat('ko-KR',{dateStyle:'medium',timeZone:'Asia/Seoul'}).format(new Date(value));
const uuid=()=>{if(crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);};
const secret=()=>Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
const keyPattern=/^[a-f0-9-]{36}\.[a-f0-9]{64}$/;
const blank=()=>({title:'',channelUrl:'',tagline:'',body:'',videoUrl:'',server:'unspecified',color:'mint',tags:[],characterIds:[],badges:[],tiers:[]});
const clone=value=>JSON.parse(JSON.stringify(value));
function safeChannel(url){try{return normalizeChannel(url).url;}catch{return '';}}
function safeVideo(url){try{return normalizeVideo(url);}catch{return '';}}
function achievements(c,chars){
 const tiers=(c.tiers||[]).filter(t=>t&&Object.hasOwn(CREATOR_TIERS,t.side)&&CREATOR_TIERS[t.side].includes(t.tier));
 const badges=(c.badges||[]).filter(b=>chars[b.characterId]&&['S','A','B','C'].includes(b.grade));
 if(!tiers.length&&!badges.length)return '';
 return `<div class="creator-records">${tiers.map(t=>`<span class="creator-tier">${icon('star')}<span><strong>${e(t.tier)}</strong><small>${e(CREATOR_SIDES[t.side])}${t.season?' · '+e(t.season):''}</small></span></span>`).join('')}${badges.map(b=>`<span class="creator-badge" title="${e(b.season||'시즌 미기재')}"><b class="creator-grade grade-${e(b.grade)}">${e(b.grade)}</b><span><strong>${e(chars[b.characterId].name)}</strong>${b.season?`<small>${e(b.season)}</small>`:''}</span></span>`).join('')}</div>`;
}
export function creatorCard(c,chars,{preview=false,detail=false,admin=false}={}){
 const color=Object.hasOwn(CREATOR_COLORS,c.color)?c.color:'mint',thumb=videoThumbnail(c.videoUrl),channel=safeChannel(c.channelUrl),video=safeVideo(c.videoUrl);
 const title=c.title||'나의 채널 이름',tagline=c.tagline||'어떤 플레이와 이야기를 만날 수 있나요?';
 const content=thumb?`<img src="${e(thumb)}" alt="${e(title)} 대표 영상 썸네일" loading="lazy" referrerpolicy="no-referrer"><span class="creator-video-mark">${icon('play')}대표 영상</span>`:`<div class="creator-cover-letter" aria-hidden="true">${e(Array.from(title).slice(0,2).join(''))}</div><span class="creator-cover-word">IDENTITY V · CREATOR</span>${icon('play')}`;
 return `<article class="creator-card creator-color-${color} ${detail?'is-detail':''}"><div class="creator-cover ${thumb?'has-video':''}">${!preview&&!detail?`<button type="button" data-cr="open" data-id="${e(c.id)}" aria-label="${e(title)} 채널 소개 보기">${content}</button>`:content}</div><div class="creator-card-body"><div class="creator-card-kicker"><span>${c.server&&c.server!=='unspecified'?e(CREATOR_SERVERS[c.server]||''):'제5인격 YouTube'}</span>${c.status==='hidden'?'<span class="creator-hidden">숨김</span>':c.isMine&&!preview?'<span>내 채널</span>':''}${admin&&c.reportCount?`<span class="creator-hidden">미처리 신고 ${c.reportCount}</span>`:''}</div><h${detail?'1':'2'}>${!preview&&!detail?`<button type="button" data-cr="open" data-id="${e(c.id)}">${e(title)}</button>`:e(title)}</h${detail?'1':'2'}><p class="creator-tagline">${e(tagline)}</p><div class="creator-tags">${(c.tags||[]).map(tag=>preview||detail?`<span>#${e(tag)}</span>`:`<button type="button" data-cr="tag" data-tag="${e(tag)}">#${e(tag)}</button>`).join('')}</div>${(c.characterIds||[]).length?`<div class="creator-characters">${c.characterIds.filter(id=>chars[id]).map(id=>`<span><img src="${e(chars[id].portrait)}" alt="" width="24" height="24" loading="lazy"><span>${e(chars[id].name)}</span></span>`).join('')}</div>`:''}${achievements(c,chars)}${(c.tiers?.length||c.badges?.length)?'<p class="creator-self-report">휘장·최고 티어는 작성자가 입력한 이력입니다.</p>':''}${detail&&c.body?`<div class="creator-story"><h2>채널 이야기</h2><p>${e(c.body)}</p></div>`:''}${!preview?`<div class="creator-card-bottom">${channel?`<a class="creator-channel-link" href="${e(channel)}" target="_blank" rel="noopener noreferrer">채널 보러 가기 ${icon('arrow')}</a>`:''}${detail&&video?`<a href="${e(video)}" target="_blank" rel="noopener noreferrer">대표 영상 보기 ↗</a>`:''}${!detail?`<button type="button" class="creator-text-button" data-cr="open" data-id="${e(c.id)}">${admin?'관리':'소개'}</button>`:''}</div>`:''}</div></article>`;
}
const selectOptions=(map,current,first)=>`${first?'<option value="">'+e(first)+'</option>':''}${Object.entries(map).map(([value,label])=>`<option value="${e(value)}" ${value===current?'selected':''}>${e(label)}</option>`).join('')}`;
const characterOptions=(characters,selected='')=>`<option value="">캐릭터 선택</option>${Object.values(characters).sort((a,b)=>a.name.localeCompare(b.name,'ko')).map(c=>`<option value="${e(c.id)}" ${c.id===selected?'selected':''}>${e(c.name)}</option>`).join('')}`;
const field=(label,name,value,{max=100,placeholder='',required=false,type='text'}={})=>`<label>${label}${required?'<span class="creator-required">필수</span>':''}<input name="${name}" type="${type}" value="${e(value)}" maxlength="${max}" placeholder="${e(placeholder)}" ${required?'required':''}></label>`;
export function creatorEditor(c,characters,{editing=false,mobile=false}={}){
 return `<div class="creator-editor-heading"><button class="creator-text-button" type="button" data-cr="back">← 채널 목록</button><div class="eyebrow">YOUR CHANNEL, YOUR STORY</div><h1>${editing?'채널 소개를 다듬어 보세요.':'나만의 채널을 소개해 주세요.'}</h1><p>처음 올린 영상 하나부터, 오래 쌓아 온 플레이까지.</p></div><div class="creator-editor-layout"><form class="creator-form" data-cr-form="editor"><section><div class="creator-section-heading"><span>01</span><div><h2>채널을 만나는 첫인상</h2><p>채널 주소와 짧은 소개로 시작해 보세요.</p></div></div>${field('채널 이름','title',c.title,{max:50,required:true,placeholder:'YouTube에 표시되는 채널 이름'})}${field('YouTube 채널 주소','channelUrl',c.channelUrl,{max:300,required:true,placeholder:'https://www.youtube.com/@채널핸들'})}${field('한 줄 소개','tagline',c.tagline,{max:120,required:true,placeholder:'시청자가 이 채널을 좋아하게 될 이유를 알려주세요.'})}<div class="creator-form-grid"><label>주로 플레이하는 서버<select name="server">${selectOptions(CREATOR_SERVERS,c.server)}</select></label>${field('대표 영상 주소 · 선택','videoUrl',c.videoUrl,{max:300,placeholder:'영상 또는 Shorts 주소'})}</div><p class="creator-field-help">대표 영상을 넣으면 썸네일이 카드에 표시됩니다.</p></section><section><div class="creator-section-heading"><span>02</span><div><h2>#우리채널만의매력</h2><p>추천 태그를 고르거나 직접 만들어 보세요. 최대 6개.</p></div></div><div class="creator-tag-suggestions" data-cr-list="suggestions"></div><div class="creator-input-row">${field('나만의 태그','customTag','',{max:19,placeholder:'#차분한해설'})}<button class="btn" type="button" data-cr="add-tag">추가</button></div><div class="creator-edit-chips" data-cr-list="tags" aria-label="선택한 태그"></div><label>주로 다루는 캐릭터 · 최대 3명<div class="creator-input-row"><select name="characterPick">${characterOptions(characters)}</select><button class="btn" type="button" data-cr="add-character">추가</button></div></label><div class="creator-edit-chips" data-cr-list="characters"></div></section><section><div class="creator-section-heading"><span>03</span><div><h2>쌓아 온 플레이 기록</h2><p>휘장과 최고 티어는 선택 사항이에요. 없어도 등록할 수 있어요.</p></div></div><div class="creator-tier-inputs">${Object.entries(CREATOR_SIDES).map(([side,label])=>{const t=c.tiers.find(t=>t.side===side);return `<div class="creator-form-grid"><label>${label} 최고 티어<select name="tier-${side}"><option value="">표시 안 함</option>${CREATOR_TIERS[side].map(tier=>`<option ${t?.tier===tier?'selected':''}>${e(tier)}</option>`).join('')}</select></label>${field('시즌 · 선택','season-'+side,t?.season||'',{max:24,placeholder:'예: 시즌 42'})}</div>`;}).join('')}</div><div class="creator-badge-builder"><h3>역대 캐릭터 휘장 <small>최대 6개</small></h3><div class="creator-badge-inputs"><label>캐릭터<select name="badgeCharacter">${characterOptions(characters)}</select></label><label>등급<select name="badgeGrade">${['S','A','B','C'].map(g=>`<option value="${g}">${g} 휘장</option>`).join('')}</select></label>${field('시즌 · 선택','badgeSeason','',{max:24,placeholder:'시즌 42'})}<button class="btn" type="button" data-cr="add-badge">추가</button></div><div class="creator-edit-chips" data-cr-list="badges"></div></div><p class="creator-field-help">기록은 직접 입력한 이력으로 표시됩니다.</p></section><section><div class="creator-section-heading"><span>04</span><div><h2>나의 색과 이야기</h2><p>채널의 분위기를 카드에 담아 보세요.</p></div></div><fieldset class="creator-color-picker"><legend>카드 색상</legend>${Object.entries(CREATOR_COLORS).map(([value,label])=>`<label class="creator-color-option creator-color-${value}"><input type="radio" name="color" value="${value}" ${value===c.color?'checked':''}><span aria-hidden="true"></span><small>${label}</small></label>`).join('')}</fieldset><label>자세한 채널 소개 · 선택<textarea name="body" rows="6" maxlength="1800" placeholder="자주 다루는 콘텐츠, 방송 일정, 시청자에게 전하고 싶은 이야기를 자유롭게 적어주세요.">${e(c.body)}</textarea></label><p class="creator-field-help"><span data-cr-count>${c.body.length}</span> / 1,800자</p></section><div class="creator-editor-actions"><p>등록하면 모든 방문자에게 공개됩니다. 제5인격 관련 채널을 소개해 주세요.</p><div><button type="button" class="btn" data-cr="preview">미리보기</button><button type="submit" class="btn primary">${editing?'수정 저장':'채널 등록하기'} ${icon('arrow')}</button></div></div><p class="creator-form-error" role="alert" hidden></p></form><aside class="creator-preview"><details ${mobile?'':'open'}><summary>내 카드 미리보기</summary><div data-cr-preview>${creatorCard(c,characters,{preview:true})}</div></details><p>입력한 내용이 미리보기에 바로 반영됩니다.</p></aside></div>`;
}

let memoryToken='',pendingVisitor;
const token=()=>{try{return localStorage.getItem('manor-feedback-visitor')||memoryToken;}catch{return memoryToken;}};
function saveToken(value){memoryToken=value;try{if(value)localStorage.setItem('manor-feedback-visitor',value);else localStorage.removeItem('manor-feedback-visitor');}catch{}}
const memoryKeys=new Map();
function savedKey(id){if(memoryKeys.has(id))return memoryKeys.get(id);try{const value=localStorage.getItem('manor-creator-key:'+id);return keyPattern.test(value||'')?value:'';}catch{return '';}}
function saveKey(id,value){memoryKeys.set(id,value);try{localStorage.setItem('manor-creator-key:'+id,value);}catch{}}

export function mountCreators(root,{characters={},postId='',navigate,admin=false,origin=CREATOR_ORIGIN}={}){
 let alive=true,busy=false,version=0,mode='public',view='list',items=[],nextPage=null,selected=null,draft=blank(),requestId=uuid(),manageSecret=secret(),searchTimer;
 const filters={q:'',tag:'',server:'',character:'',status:'',reported:admin?'1':''},controllers=new Set();
 let lastFocus=null;
 const frame=html=>{if(!alive)return;root.innerHTML=`<section class="creator-board ${admin?'creator-admin':''}"><div class="creator-notice" role="status" aria-live="polite" hidden></div>${html}<dialog class="creator-dialog" aria-label="채널 게시판 대화상자"></dialog></section>`;};
 const notice=(message,error=false)=>{const node=root.querySelector('.creator-notice');if(node){node.hidden=!message;node.textContent=message;node.classList.toggle('is-error',error);}};
 async function api(path,{method='GET',body,guest=true}={}){
  const controller=new AbortController();controllers.add(controller);const timeout=setTimeout(()=>controller.abort(),15000),headers={};
  if(body!==undefined)headers['Content-Type']='application/json';if(admin)headers['X-Manor-Admin']='1';else if(guest&&token())headers.Authorization='Bearer '+token();
  try{const response=await fetch(origin+path,{method,headers,body:body===undefined?undefined:JSON.stringify(body),credentials:admin?'same-origin':'omit',cache:'no-store',signal:controller.signal});let data;try{data=await response.json();}catch{throw Error('서버 응답을 확인하지 못했습니다. 잠시 후 다시 시도해 주세요.');}
   if(!response.ok){if(data.code==='visitor_invalid'){saveToken('');if(method==='GET')return api(path,{guest:false});}const error=Error(data.error||'요청을 처리하지 못했습니다.');error.status=response.status;throw error;}return data;
  }catch(error){if(error.name==='AbortError')throw Error('연결이 지연되고 있습니다. 입력한 내용은 유지되니 다시 시도해 주세요.');if(error instanceof TypeError)throw Error('서버에 연결하지 못했습니다. 네트워크 상태를 확인해 주세요.');throw error;}finally{clearTimeout(timeout);controllers.delete(controller);}
 }
 async function ensureVisitor(){if(admin||token())return;if(!pendingVisitor)pendingVisitor=api('/api/feedback/visitors',{method:'POST',body:{},guest:false}).then(data=>saveToken(data.token)).finally(()=>pendingVisitor=null);await pendingVisitor;}
 const prefix=admin?'/api/admin/creators':'/api/creators';
 function heading(){return `<header class="creator-heading"><div><div class="eyebrow">${admin?'CREATOR DESK':'MANOR CREATORS'}</div><h1>${admin?'유튜브 게시판 관리':'함께 보는 제5인격.'}</h1><p>${admin?'신고된 내용을 확인하고 공개 상태를 관리합니다.':'좋아하는 플레이를 찾고, 나만의 채널을 소개하세요.'}</p>${admin?'':'<span class="creator-open-note">구독자 수, 티어 상관없이 누구나.</span>'}</div>${admin?'<button class="btn" data-cr="reload" type="button">새로고침</button>':`<button class="btn primary" data-cr="compose" type="button">${icon('plus')}내 채널 등록</button>`}</header>`;}
 function toolbar(){return `<div class="creator-toolbar"><div class="creator-tabs" role="group" aria-label="채널 목록 보기">${admin?`<button type="button" data-cr="reported" aria-pressed="${filters.reported==='1'}">신고 접수</button><button type="button" data-cr="all-admin" aria-pressed="${!filters.reported}">전체 채널</button>`:`<button type="button" data-cr="public" aria-pressed="${mode==='public'}">모든 채널</button><button type="button" data-cr="mine" aria-pressed="${mode==='mine'}">내 채널</button>`}</div><label class="creator-search">${icon('search')}<span class="visually-hidden">채널과 태그 검색</span><input type="search" name="creatorSearch" value="${e(filters.q)}" placeholder="채널 이름, 소개, #태그 검색" maxlength="100"></label><label><span class="visually-hidden">채널 서버 필터</span><select data-cr-filter="server">${selectOptions(CREATOR_SERVERS,filters.server,'모든 서버')}</select></label><label><span class="visually-hidden">주력 캐릭터 필터</span><select data-cr-filter="character">${characterOptions(characters,filters.character).replace('캐릭터 선택','모든 캐릭터')}</select></label></div><div class="creator-discovery-tags" role="group" aria-label="콘텐츠 태그">${['',...CREATOR_TAGS.slice(0,10)].map(tag=>`<button type="button" data-cr="tag" data-tag="${e(tag)}" aria-pressed="${filters.tag===tag}">${tag?'#'+e(tag):'전체 태그'}</button>`).join('')}${filters.tag&&!CREATOR_TAGS.slice(0,10).includes(filters.tag)?`<button type="button" data-cr="tag" data-tag="${e(filters.tag)}" aria-pressed="true">#${e(filters.tag)}</button>`:''}</div>${mode==='mine'&&!admin?'<p class="creator-mine-note">이 브라우저에서 등록하거나 관리키를 연결한 채널입니다. <button type="button" class="creator-text-button" data-cr="recover">관리키로 연결</button></p>':''}`;}
 function listShell(){view='list';selected=null;frame(heading()+`<div data-cr-toolbar>${toolbar()}</div><div data-cr-results aria-live="polite"><div class="creator-empty"><span class="loading-orbit" aria-hidden="true"></span><p>채널을 불러오고 있습니다.</p></div></div>`);}
 function results(data,append){
  items=append?[...items,...data.creators.filter(c=>!items.some(x=>x.id===c.id))]:data.creators;nextPage=data.nextPage;
  const filtered=filters.q||filters.tag||filters.server||filters.character;
  const empty=admin?'이 목록에 채널이 없습니다.':filtered?'조건에 맞는 채널이 없습니다.':mode==='mine'?'아직 등록한 채널이 없습니다.':'첫 번째 채널을 소개해 주세요.';
  root.querySelector('[data-cr-results]').innerHTML=`<div class="creator-results-heading"><p>${mode==='mine'?'내 채널':'등록된 채널'} <strong>${data.total}</strong></p><span>${filtered?'<button type="button" class="creator-text-button" data-cr="reset">필터 초기화</button>':'새로 등록한 순서'}</span></div>${items.length?`<div class="creator-grid">${items.map(c=>creatorCard(c,characters,{admin})).join('')}</div>`:`<div class="creator-empty">${icon('play')}<h2>${empty}</h2><p>${admin?'접수된 신고는 이곳에서 처리할 수 있습니다.':filtered?'다른 태그를 고르거나 검색어를 바꿔 보세요.':'공략도, 웃긴 순간도, 첫 랭크 영상도 좋아요.<br>나만의 플레이를 기다리는 시청자를 만나보세요.'}</p>${admin?'':`<button class="btn ${filtered?'':'primary'}" type="button" data-cr="${filtered?'reset':'compose'}">${filtered?'전체 채널 보기':'내 채널 등록하기'}</button>`}</div>`}${nextPage!==null?'<button type="button" class="btn creator-more" data-cr="more">채널 더 보기</button>':''}<p class="creator-board-note">${admin?'신고만으로 자동 숨김 처리하지 않습니다.':'제5인격 콘텐츠를 자유롭게 소개하는 공간입니다. 채널 규모나 티어로 등록을 제한하지 않습니다.'}</p>`;
 }
 async function loadList(append=false){
  const current=++version;
  if(view!=='list'||!root.querySelector('[data-cr-results]'))listShell();
  if(mode==='mine'&&!token()&&!admin){results({creators:[],total:0,nextPage:null},false);return;}
  root.querySelector('[data-cr-results]').setAttribute('aria-busy','true');
  const query=new URLSearchParams({...filters,page:String(append?nextPage:0)});
  try{const data=await api(prefix+(mode==='mine'&&!admin?'/mine':'')+'?'+query);if(alive&&version===current&&view==='list')results(data,append);}
  catch(error){if(alive&&version===current&&view==='list'){root.querySelector('[data-cr-results]').innerHTML=`<div class="creator-empty"><h2>채널을 불러오지 못했습니다.</h2><p>${e(error.message)}</p><button type="button" class="btn" data-cr="reload">다시 시도</button></div>`;}}
  finally{if(alive&&version===current)root.querySelector('[data-cr-results]')?.removeAttribute('aria-busy');}
 }
 function move(id=''){closeDialog();if(navigate){navigate(id);return;}postId=id;return id?loadDetail(id):loadList();}
 function manageControls(c){return `<div class="creator-detail-tools"><button class="creator-text-button" type="button" data-cr="back">← 채널 목록</button><div>${admin?'':c.isMine?`<button type="button" class="btn small" data-cr="edit">소개 수정</button><button type="button" class="btn small" data-cr="key">${icon('key')}관리키</button><button type="button" class="creator-text-button" data-cr="delete">삭제</button>`:`<button type="button" class="creator-text-button" data-cr="recover">내 게시글 관리</button><button type="button" class="creator-text-button" data-cr="report">신고</button>`}</div></div>`;}
 async function loadDetail(id){
  const current=++version;view='detail';frame('<div class="creator-empty" role="status"><span class="loading-orbit" aria-hidden="true"></span><p>채널 소개를 불러오고 있습니다.</p></div>');
  try{const data=await api(prefix+'/'+encodeURIComponent(id));if(!alive||version!==current)return;selected=data.creator;
   const reports=admin?await api(prefix+'/'+encodeURIComponent(id)+'/reports'):null;if(!alive||version!==current)return;
   frame(manageControls(selected)+`<div class="creator-detail-layout">${creatorCard(selected,characters,{detail:true,admin})}${admin?reviewForm(selected,reports.reports):selected.isMine?`<aside class="creator-owner-note"><h2>${selected.status==='hidden'?'현재 숨김 처리된 채널입니다.':'내 채널이 공개되어 있습니다.'}</h2><p>${selected.status==='hidden'?'내용을 수정해도 자동으로 다시 공개되지는 않습니다. 운영자에게 재검토를 요청해 주세요.':'소개와 기록은 언제든 수정할 수 있습니다. 관리키를 따로 보관하면 다른 기기에서도 게시글을 관리할 수 있어요.'}</p>${selected.moderationReason?`<h3>운영자 안내</h3><p>${e(selected.moderationReason)}</p>`:''}<p>등록 ${e(date(selected.createdAt))}<br>최근 수정 ${e(date(selected.updatedAt))}</p><button class="btn" data-cr="key" type="button">관리키 확인</button></aside>`:''}</div>`);
  }catch(error){if(alive&&version===current){frame('<div class="creator-empty"><h2>채널을 열 수 없습니다.</h2><button class="btn" data-cr="back" type="button">목록으로 돌아가기</button></div>');notice(error.message,true);}}
 }
 function reviewForm(c,reports){return `<aside><section class="creator-owner-note"><h2>신고 내역</h2>${reports.length?reports.map(r=>`<div class="creator-report-row"><strong>${e(CREATOR_REPORTS[r.reason]||r.reason)} ${r.resolved?'· 처리됨':''}</strong><p>${e(r.detail||'추가 내용 없음')}</p><small>${e(date(r.createdAt))}</small></div>`).join(''):'<p>접수된 신고가 없습니다.</p>'}</section><form class="creator-form creator-review-form" data-cr-form="moderate"><label>공개 상태<select name="status"><option value="published" ${c.status==='published'?'selected':''}>공개</option><option value="hidden" ${c.status==='hidden'?'selected':''}>숨김</option></select></label><label>작성자에게 전달할 처리 사유<textarea name="reason" rows="4" maxlength="500" ${c.status==='hidden'?'required':''}>${e(c.moderationReason)}</textarea></label><label class="creator-checkbox"><input type="checkbox" name="resolveReports" checked>접수된 신고를 처리 완료로 표시</label><button class="btn primary" type="submit">처리 결과 저장</button><p class="creator-form-error" role="alert" hidden></p></form></aside>`;}
 function collect(){const form=root.querySelector('[data-cr-form="editor"]');if(!form)return draft;const data=new FormData(form);for(const name of ['title','channelUrl','tagline','body','videoUrl','server','color'])draft[name]=String(data.get(name)||'');draft.tiers=Object.keys(CREATOR_SIDES).filter(side=>data.get('tier-'+side)).map(side=>({side,tier:String(data.get('tier-'+side)),season:String(data.get('season-'+side)||'')}));return draft;}
 function preview(){collect();const node=root.querySelector('[data-cr-preview]');if(node)node.innerHTML=creatorCard(draft,characters,{preview:true});const count=root.querySelector('[data-cr-count]');if(count)count.textContent=String(draft.body.length);}
 function editLists(){
  const set=(key,html)=>{const n=root.querySelector('[data-cr-list="'+key+'"]');if(n)n.innerHTML=html;};
  set('suggestions',CREATOR_TAGS.map(tag=>`<button type="button" data-cr="suggest-tag" data-tag="${e(tag)}" aria-pressed="${draft.tags.includes(tag)}">#${e(tag)}</button>`).join(''));
  set('tags',draft.tags.map((tag,i)=>`<button type="button" data-cr="remove-tag" data-index="${i}" aria-label="${e(tag)} 태그 제거">#${e(tag)} ${icon('close')}</button>`).join(''));
  set('characters',draft.characterIds.map((id,i)=>`<button type="button" data-cr="remove-character" data-index="${i}" aria-label="${e(characters[id].name)} 제거">${e(characters[id].name)} ${icon('close')}</button>`).join(''));
  set('badges',draft.badges.map((b,i)=>`<button type="button" data-cr="remove-badge" data-index="${i}" aria-label="${e(characters[b.characterId].name)} ${b.grade} 휘장 제거"><b class="creator-grade grade-${b.grade}">${b.grade}</b>${e(characters[b.characterId].name)}${b.season?' · '+e(b.season):''} ${icon('close')}</button>`).join(''));
  preview();
 }
 function editor(c=null){++version;view='editor';selected=c;draft=c?clone(c):blank();requestId=uuid();manageSecret=secret();frame(creatorEditor(draft,characters,{editing:!!c,mobile:root.ownerDocument.defaultView.matchMedia('(max-width:800px)').matches}));editLists();root.querySelector('[name="title"]')?.focus();}
 function showDialog(title,html){const dialog=root.querySelector('.creator-dialog');lastFocus=root.ownerDocument.activeElement;dialog.innerHTML=`<div class="creator-dialog-head"><h2>${e(title)}</h2><button type="button" class="icon-btn" data-cr="close" aria-label="닫기">${icon('close')}</button></div><div class="creator-dialog-body">${html}</div>`;dialog.showModal();}
 function closeDialog(){const dialog=root.querySelector('.creator-dialog');if(dialog?.open){dialog.close();lastFocus?.focus?.();}}
 function recoverDialog(){showDialog('내 채널 연결하기','<form class="creator-form" data-cr-form="recover"><p>등록할 때 받은 관리키로 이 브라우저에 수정 권한을 연결합니다.</p><label>관리키<input name="key" autocomplete="off" spellcheck="false" required placeholder="게시글 ID.관리키"></label><button class="btn primary" type="submit">내 채널 연결</button><p class="creator-form-error" role="alert" hidden></p></form>');}
 function keyDialog(){const key=savedKey(selected.id);showDialog('이 채널의 관리키',key?`<p>이 키로 다른 기기에서도 수정·삭제할 수 있습니다. 공개 소개에 적거나 다른 사람에게 공유하지 마세요.</p><label class="creator-key-label">관리키<input name="manageKey" value="${e(key)}" readonly autocomplete="off" spellcheck="false"></label><button class="btn primary" data-cr="copy-key" type="button">관리키 복사</button><p class="creator-copy-status" role="status"></p>`:'<p>이 브라우저에는 관리키가 저장되어 있지 않습니다. 현재 브라우저에서는 계속 수정할 수 있습니다. 처음 등록한 기기에 보관한 키를 확인해 주세요.</p>');}
 const formError=(form,message)=>{const n=form.querySelector('.creator-form-error');if(n){n.textContent=message;n.hidden=!message;}};
 function refreshToolbar(){root.querySelector('[data-cr-toolbar]').innerHTML=toolbar();}
 async function click(event){
  const button=event.target.closest('[data-cr]');if(!button||!root.contains(button))return;event.preventDefault();if(busy)return;
  const action=button.dataset.cr;
  try{
   if(action==='close')return closeDialog();
   if(action==='compose')return editor();if(action==='edit'&&selected?.isMine)return editor(selected);
   if(action==='back')return move();if(action==='open')return move(button.dataset.id);if(action==='reload')return view==='detail'?loadDetail(postId):loadList();if(action==='more')return loadList(true);
   if(['public','mine','reported','all-admin','tag','reset'].includes(action)){
    if(action==='public'||action==='mine')mode=action;
    if(action==='reported')filters.reported='1';if(action==='all-admin')filters.reported='';
    if(action==='tag')filters.tag=filters.tag===button.dataset.tag?'':button.dataset.tag;
    if(action==='reset')Object.assign(filters,{q:'',tag:'',server:'',character:''});
    clearTimeout(searchTimer);refreshToolbar();return loadList();
   }
   if(action==='recover')return recoverDialog();if(action==='key')return keyDialog();
   if(action==='copy-key'){const input=root.querySelector('[name="manageKey"]'),status=root.querySelector('.creator-copy-status');try{await navigator.clipboard.writeText(input.value);status.textContent='복사했습니다.';}catch{input.focus();input.select();status.textContent='선택한 관리키를 직접 복사해 주세요.';}return;}
   if(action==='delete')return showDialog('채널 소개를 삭제할까요?','<form class="creator-form" data-cr-form="delete"><p>등록한 소개가 게시판에서 사라집니다. YouTube 채널과 영상은 삭제되지 않습니다.</p><button class="btn primary" type="submit">게시글 삭제</button><button class="btn" data-cr="close" type="button">취소</button><p class="creator-form-error" role="alert" hidden></p></form>');
   if(action==='report')return showDialog('채널 신고','<form class="creator-form" data-cr-form="report"><label>신고 이유<select name="reason">'+selectOptions(CREATOR_REPORTS,'spam')+'</select></label><label>추가 설명 · 선택<textarea name="detail" rows="4" maxlength="500" placeholder="확인이 필요한 내용을 알려주세요."></textarea></label><p class="creator-field-help">신고 내용은 운영자만 확인합니다.</p><button class="btn primary" type="submit">신고 접수</button><p class="creator-form-error" role="alert" hidden></p></form>');
   if(action==='preview'){collect();return showDialog('내 카드 미리보기',creatorCard(draft,characters,{preview:true}));}
   if(view!=='editor')return;collect();const form=root.querySelector('[data-cr-form="editor"]');formError(form,'');
   if(['add-tag','suggest-tag'].includes(action)){
    const input=form.querySelector('[name="customTag"]'),tag=normalizeTag(action==='suggest-tag'?button.dataset.tag:input.value),index=draft.tags.findIndex(t=>t.toLocaleLowerCase('en-US')===tag.toLocaleLowerCase('en-US'));
    if(index>=0){if(action==='suggest-tag')draft.tags.splice(index,1);else throw Error('이미 선택한 태그입니다.');}else{if(draft.tags.length>=6)throw Error('태그는 최대 6개까지 추가할 수 있습니다.');draft.tags.push(tag);}if(action==='add-tag')input.value='';
   }
   if(action==='add-character'){const id=form.querySelector('[name="characterPick"]').value;if(!characters[id])throw Error('캐릭터를 선택해 주세요.');if(draft.characterIds.includes(id))throw Error('이미 선택한 캐릭터입니다.');if(draft.characterIds.length>=3)throw Error('캐릭터는 최대 3명까지 추가할 수 있습니다.');draft.characterIds.push(id);}
   if(action==='add-badge'){const id=form.querySelector('[name="badgeCharacter"]').value,grade=form.querySelector('[name="badgeGrade"]').value,season=form.querySelector('[name="badgeSeason"]').value.trim();if(!characters[id])throw Error('휘장의 캐릭터를 선택해 주세요.');if(draft.badges.length>=6)throw Error('휘장은 최대 6개까지 추가할 수 있습니다.');if(draft.badges.some(b=>b.characterId===id&&b.season===season))throw Error('같은 캐릭터·시즌의 휘장이 이미 있습니다.');draft.badges.push({characterId:id,grade,season});}
   const arrays={'remove-tag':'tags','remove-character':'characterIds','remove-badge':'badges'};if(arrays[action])draft[arrays[action]].splice(Number(button.dataset.index),1);editLists();
  }catch(error){const form=root.querySelector('[data-cr-form="editor"]');if(form)formError(form,error.message);else notice(error.message,true);}
 }
 function change(event){if(busy)return;if(event.target.matches('[data-cr-filter]')){filters[event.target.dataset.crFilter]=event.target.value;clearTimeout(searchTimer);loadList();}if(event.target.closest('[data-cr-form="editor"]'))preview();if(event.target.name==='status'){const form=event.target.closest('[data-cr-form="moderate"]');if(form)form.querySelector('[name="reason"]').required=event.target.value==='hidden';}}
 function input(event){if(busy)return;if(event.target.name==='creatorSearch'){filters.q=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadList(),280);}if(event.target.closest('[data-cr-form="editor"]'))preview();}
 async function submit(event){
  const form=event.target.closest('[data-cr-form]');if(!form||!root.contains(form))return;event.preventDefault();if(busy)return;busy=true;formError(form,'');const buttons=[...form.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);
  try{const kind=form.dataset.crForm,data=new FormData(form);
   if(kind==='editor'){
    const value=normalizeCreator(collect(),new Map(Object.entries(characters)));delete value.channelKey;
    await ensureVisitor();const editing=selected?.id;
    const result=await api(prefix+(editing?'/'+editing:''),{method:editing?'PATCH':'POST',body:{...value,...(editing?{revision:selected.revision}:{requestId,manageSecret})}});if(!alive)return;
    if(!editing)saveKey(result.creator.id,result.creator.id+'.'+manageSecret);busy=false;return move(result.creator.id);
   }
   if(kind==='recover'){
    const key=String(data.get('key')||'').trim();if(!keyPattern.test(key))throw Error('관리키 전체를 입력해 주세요.');await ensureVisitor();const result=await api('/api/creators/access',{method:'POST',body:{key}});if(!alive)return;saveKey(result.creator.id,key);busy=false;return move(result.creator.id);
   }
   if(kind==='delete'){await api(prefix+'/'+selected.id,{method:'DELETE',body:{revision:selected.revision}});if(!alive)return;busy=false;return move();}
   if(kind==='report'){await ensureVisitor();await api(prefix+'/'+selected.id+'/reports',{method:'POST',body:{reason:data.get('reason'),detail:data.get('detail')}});if(!alive)return;busy=false;closeDialog();notice('신고를 접수했습니다. 운영자가 내용을 확인합니다.');return;}
   if(kind==='moderate'){const result=await api(prefix+'/'+selected.id,{method:'PATCH',body:{status:data.get('status'),reason:data.get('reason'),revision:selected.revision,resolveReports:data.get('resolveReports')==='on'}});if(!alive)return;busy=false;await loadDetail(result.creator.id);notice('처리 결과를 저장했습니다.');}
  }catch(error){if(alive){formError(form,error.message);if(error.status===409)notice('최신 상태를 확인한 뒤 다시 시도해 주세요. 입력한 내용은 유지됩니다.',true);}}
  finally{busy=false;if(alive)buttons.forEach(b=>b.disabled=false);}
 }
 function keydown(event){if(event.key==='Enter'&&event.target.name==='customTag'){event.preventDefault();root.querySelector('[data-cr="add-tag"]')?.click();}}
 function imageError(event){const img=event.target;if(img.tagName==='IMG'&&img.closest('.creator-cover')){img.hidden=true;img.closest('.creator-cover').classList.add('thumbnail-failed');}}
 root.addEventListener('click',click);root.addEventListener('change',change);root.addEventListener('input',input);root.addEventListener('submit',submit);root.addEventListener('keydown',keydown);root.addEventListener('error',imageError,true);
 if(postId)loadDetail(postId);else{listShell();loadList();}
 return ()=>{alive=false;version++;clearTimeout(searchTimer);controllers.forEach(c=>c.abort());root.removeEventListener('click',click);root.removeEventListener('change',change);root.removeEventListener('input',input);root.removeEventListener('submit',submit);root.removeEventListener('keydown',keydown);root.removeEventListener('error',imageError,true);root.querySelector('.creator-dialog')?.close();};
}
